local LibraryCatalogMaker = {}
local PRODUCTS = {
    simple_parchment_catalog = { name = "Preprost pergamentni katalog", parchmentCost = 3, woodCost = 1, time = 4, cost = 70, education = 18, happiness = 1, description = "Preprost pergamentni katalog za knjižnico." },
    leather_bound_catalog = { name = "Usnjeni vezani katalog", parchmentCost = 3, leatherCost = 1, woodCost = 1, time = 6, cost = 180, education = 32, happiness = 1, prestige = 2, description = "Usnjeni vezani katalog za trgovce." },
    silver_clasped_catalog = { name = "Srebrnosponka katalog", parchmentCost = 3, silverCost = 1, leatherCost = 1, woodCost = 1, time = 9, cost = 440, education = 48, happiness = 2, prestige = 6, description = "Srebrnosponka katalog za plemiče." },
    gold_trimmed_catalog = { name = "Zlatookrasni katalog", parchmentCost = 3, goldCost = 1, silverCost = 1, leatherCost = 1, woodCost = 1, time = 13, cost = 1000, education = 62, happiness = 3, prestige = 14, description = "Zlatookrasni katalog za visoke plemiče." },
    jewel_set_catalog = { name = "Draguljasta katalog", parchmentCost = 4, goldCost = 1, silverCost = 1, leatherCost = 1, woodCost = 1, jewelCost = 1, time = 17, cost = 2200, education = 78, happiness = 5, prestige = 27, description = "Katalog z draguljem za visoko plemstvo." },
    royal_grand_catalog = { name = "Kraljevski veliki katalog", parchmentCost = 5, goldCost = 2, silverCost = 2, leatherCost = 1, woodCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 4800, education = 92, happiness = 12, prestige = 58, description = "Veliki kraljevski katalog z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    catalog_workshop = { name = "Katalogna delavnica", cost = { gold = 240, wood = 100, stone = 100, parchment = 6 }, upkeep = 5, qualityBonus = 5 },
    archive_loft = { name = "Arhivska podstrešje", cost = { gold = 880, wood = 240, stone = 220, silver = 6, leather = 6 }, upkeep = 20, qualityBonus = 18 },
    master_archivist_atelier = { name = "Mojstrski arhivski atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_archive_palace = { name = "Kraljevska arhivska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
LibraryCatalogMaker.parchmentStock = 16; LibraryCatalogMaker.woodStock = 10; LibraryCatalogMaker.leatherStock = 10; LibraryCatalogMaker.silverStock = 6; LibraryCatalogMaker.goldStock = 6; LibraryCatalogMaker.jewelStock = 4; LibraryCatalogMaker.pearlStock = 4
LibraryCatalogMaker.productStock = {}; LibraryCatalogMaker.buildings = {}; LibraryCatalogMaker.maker = nil; LibraryCatalogMaker.activeMaking = {}; LibraryCatalogMaker.totalProducts = 0; LibraryCatalogMaker.dayTimer = 0
function LibraryCatalogMaker.init() LibraryCatalogMaker.parchmentStock=16; LibraryCatalogMaker.woodStock=10; LibraryCatalogMaker.leatherStock=10; LibraryCatalogMaker.silverStock=6; LibraryCatalogMaker.goldStock=6; LibraryCatalogMaker.jewelStock=4; LibraryCatalogMaker.pearlStock=4; LibraryCatalogMaker.productStock={}; LibraryCatalogMaker.buildings={}; LibraryCatalogMaker.maker=nil; LibraryCatalogMaker.activeMaking={}; LibraryCatalogMaker.totalProducts=0; LibraryCatalogMaker.dayTimer=0; print("[LibraryCatalogMaker] Royal Library Catalog Maker System initialized (6 products, 4 buildings)") end
function LibraryCatalogMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LibraryCatalogMaker.maker={name=n or ("Katalogar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Katalogar najet: %s (spretnost: %d)",LibraryCatalogMaker.maker.name,s),"success") end; return true end
function LibraryCatalogMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LibraryCatalogMaker.build(id) local ok,e=LibraryCatalogMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LibraryCatalogMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LibraryCatalogMaker.getQualityBonus() local b=0; for _,bd in ipairs(LibraryCatalogMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LibraryCatalogMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.parchmentCost and LibraryCatalogMaker.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.woodCost and LibraryCatalogMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and LibraryCatalogMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LibraryCatalogMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LibraryCatalogMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LibraryCatalogMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LibraryCatalogMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LibraryCatalogMaker.buildings==0 then return false,"Potrebna katalogna delavnica" end; if not LibraryCatalogMaker.maker then return false,"Potreben katalogar" end; return true end
function LibraryCatalogMaker.make(pt,qty) qty=qty or 1; local ok,e=LibraryCatalogMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.parchmentCost then LibraryCatalogMaker.parchmentStock=LibraryCatalogMaker.parchmentStock-d.parchmentCost*qty end; if d.woodCost then LibraryCatalogMaker.woodStock=LibraryCatalogMaker.woodStock-d.woodCost*qty end; if d.leatherCost then LibraryCatalogMaker.leatherStock=LibraryCatalogMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then LibraryCatalogMaker.silverStock=LibraryCatalogMaker.silverStock-d.silverCost*qty end; if d.goldCost then LibraryCatalogMaker.goldStock=LibraryCatalogMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LibraryCatalogMaker.jewelStock=LibraryCatalogMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LibraryCatalogMaker.pearlStock=LibraryCatalogMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LibraryCatalogMaker.maker then t=math.max(1,t-math.floor(LibraryCatalogMaker.maker.skill/13)) end; table.insert(LibraryCatalogMaker.activeMaking,{id="catalog_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,education=d.education or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LibraryCatalogMaker.completeMaking(m) local q=1.0+(LibraryCatalogMaker.getQualityBonus()/100); if LibraryCatalogMaker.maker then q=q+(LibraryCatalogMaker.maker.skill/140) end; q=math.min(2.5,q); LibraryCatalogMaker.productStock[m.productType]=(LibraryCatalogMaker.productStock[m.productType] or 0)+m.quantity; LibraryCatalogMaker.totalProducts=LibraryCatalogMaker.totalProducts+m.quantity; if m.education>0 and _G.state then _G.state.education=(_G.state.education or 0)+m.education end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LibraryCatalogMaker.maker then LibraryCatalogMaker.maker.itemsMade=LibraryCatalogMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LibraryCatalogMaker.maker.skill=math.min(100,LibraryCatalogMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Katalog izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"catalog.completed",{productName=m.productName,education=m.education,prestige=m.prestige,happiness=m.happiness}) end end
function LibraryCatalogMaker.update(dt) if not _G.state then return end; LibraryCatalogMaker.dayTimer=LibraryCatalogMaker.dayTimer+dt; if LibraryCatalogMaker.dayTimer>=30 then LibraryCatalogMaker.dayTimer=0; for i=#LibraryCatalogMaker.activeMaking,1,-1 do local m=LibraryCatalogMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LibraryCatalogMaker.completeMaking(m); table.remove(LibraryCatalogMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LibraryCatalogMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LibraryCatalogMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LibraryCatalogMaker.getStats() return {parchmentStock=LibraryCatalogMaker.parchmentStock,woodStock=LibraryCatalogMaker.woodStock,leatherStock=LibraryCatalogMaker.leatherStock,silverStock=LibraryCatalogMaker.silverStock,goldStock=LibraryCatalogMaker.goldStock,jewelStock=LibraryCatalogMaker.jewelStock,pearlStock=LibraryCatalogMaker.pearlStock,productStock=LibraryCatalogMaker.productStock,numBuildings=#LibraryCatalogMaker.buildings,hasMaker=LibraryCatalogMaker.maker~=nil,makerName=LibraryCatalogMaker.maker and LibraryCatalogMaker.maker.name or "—",makerSkill=LibraryCatalogMaker.maker and LibraryCatalogMaker.maker.skill or 0,activeMaking=#LibraryCatalogMaker.activeMaking,totalProducts=LibraryCatalogMaker.totalProducts} end
return LibraryCatalogMaker
